solution.common.sh:
#!/usr/bin/env bash
# common.sh A B : lines present in both files, each once, byte-wise sorted
[ $# -eq 2 ] && [ -r "$1" ] && [ -r "$2" ] || { echo "usage: common.sh A B" >&2; exit 2; }
comm -12 <(LC_ALL=C sort -u -- "$1") <(LC_ALL=C sort -u -- "$2")

